CREATE TABLE workspaces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(160) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role VARCHAR(32) NOT NULL DEFAULT 'owner', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, sku VARCHAR(100), barcode VARCHAR(100), name VARCHAR(200) NOT NULL, category VARCHAR(120) NOT NULL DEFAULT '', selling_price NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(selling_price>=0), cost_price NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(cost_price>=0), reorder_level NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(reorder_level>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workspace_id,sku), UNIQUE(workspace_id,barcode));
CREATE TABLE customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name VARCHAR(200) NOT NULL, email VARCHAR(254) NOT NULL DEFAULT '', phone VARCHAR(80) NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name VARCHAR(200) NOT NULL, contact_name VARCHAR(160) NOT NULL DEFAULT '', email VARCHAR(254) NOT NULL DEFAULT '', phone VARCHAR(80) NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', payment_terms VARCHAR(160) NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE expenses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, expense_date DATE NOT NULL, category VARCHAR(120) NOT NULL, description TEXT NOT NULL, amount NUMERIC(14,2) NOT NULL CHECK(amount>0), currency CHAR(3) NOT NULL DEFAULT 'PHP', reference VARCHAR(160) NOT NULL DEFAULT '', created_by UUID REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, title VARCHAR(240) NOT NULL, description TEXT NOT NULL DEFAULT '', priority VARCHAR(20) NOT NULL DEFAULT 'normal', due_date DATE, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE warehouses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, code VARCHAR(80) NOT NULL, name VARCHAR(200) NOT NULL, address TEXT NOT NULL DEFAULT '', status VARCHAR(30) NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workspace_id,code));
CREATE TABLE warehouse_locations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, warehouse_id UUID NOT NULL REFERENCES warehouses(id) ON DELETE CASCADE, code VARCHAR(80) NOT NULL, zone VARCHAR(80) NOT NULL DEFAULT '', location_type VARCHAR(40) NOT NULL DEFAULT 'shelf', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(warehouse_id,code));
CREATE TABLE inventory_balances (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), location_id UUID NOT NULL REFERENCES warehouse_locations(id), quantity NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(quantity>=0), reserved_quantity NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(reserved_quantity>=0 AND reserved_quantity<=quantity), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(product_id,location_id));
CREATE TABLE inventory_movements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), location_id UUID NOT NULL REFERENCES warehouse_locations(id), movement_type VARCHAR(40) NOT NULL, quantity_delta NUMERIC(14,3) NOT NULL, reference VARCHAR(160) NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', idempotency_key VARCHAR(180), created_by UUID REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key));
CREATE TABLE sales (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, sale_number VARCHAR(100) NOT NULL, customer_name VARCHAR(200) NOT NULL DEFAULT 'Walk-in customer', payment_method VARCHAR(40) NOT NULL DEFAULT 'cash', total NUMERIC(14,2) NOT NULL CHECK(total>=0), idempotency_key VARCHAR(180), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key));
CREATE TABLE sale_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sale_id UUID NOT NULL REFERENCES sales(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0), unit_price NUMERIC(14,2) NOT NULL CHECK(unit_price>=0), line_total NUMERIC(14,2) NOT NULL CHECK(line_total>=0));
CREATE TABLE audit_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, actor_user_id UUID, action VARCHAR(120) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id UUID, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_products_workspace ON products(workspace_id); CREATE INDEX idx_expenses_workspace_date ON expenses(workspace_id,expense_date); CREATE INDEX idx_tasks_workspace ON tasks(workspace_id); CREATE INDEX idx_inventory_workspace ON inventory_balances(workspace_id);
CREATE TABLE purchase_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, supplier_id UUID NOT NULL REFERENCES suppliers(id), warehouse_id UUID NOT NULL REFERENCES warehouses(id), order_number VARCHAR(120) NOT NULL, notes TEXT NOT NULL DEFAULT '', currency CHAR(3) NOT NULL DEFAULT 'PHP', status VARCHAR(30) NOT NULL DEFAULT 'open', total NUMERIC(14,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workspace_id,order_number));
CREATE TABLE purchase_order_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id UUID NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0), received_quantity NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(received_quantity>=0), unit_cost NUMERIC(14,2) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE wms_pick_lists (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), location_id UUID NOT NULL REFERENCES warehouse_locations(id), quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0), order_ref VARCHAR(160) NOT NULL DEFAULT '', status VARCHAR(30) NOT NULL DEFAULT 'reserved', idempotency_key VARCHAR(180), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key));
